import re, sys
text = (params.get('text') or params.get('input') or '')
if not isinstance(text, str):
    text = str(text)
if not text.strip():
    result = {'error': 'pass params.text'}
else:
    words = [w for w in re.split(r'\s+', text.strip()) if w]
    cjk = re.findall(r'[\u4e00-\u9fff\u3040-\u30ff\uac00-\ud7af]', text)
    result = {
        'chars': len(text),
        'chars_no_ws': len(re.sub(r'\s', '', text)),
        'lines': text.count('\n') + (0 if text.endswith('\n') else 1),
        'words': len(words),
        'cjk_chars': len(cjk),
    }
